class FeatureBoundary extends React.Component<Props, State> {
  state = { error: null as Error | null };

  static getDerivedStateFromError(error: Error) {
    reportToTracker(error);              // log the crash
    return { error };
  }

  handleRetry = () => {
    this.setState({ error: null });
  };

  render() {
    if (this.state.error) {
      return (
        <div role="alert">
          <p>Something broke in {this.props.featureName}.</p>
          <button onClick={this.handleRetry}>Retry</button>
        </div>
      );
    }
    return this.props.children;
  }
}
